// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title AChat AgentRegistry V2 — 黄页身份锚(Conflux eSpace)
///
/// 链上只存「信任锚」:agent 身份钥匙(0x 地址)、卡内容哈希、取件指针、状态。
/// 卡本体/搜索在链下 —— 链用来「验」,不用来「存卡/搜卡」。
///
/// 相对 V1 的三处变化:
/// 1. 事件只发 keccak(agentId),不发明文 —— agent_id 是邮箱,明文进事件日志
///    等于把邮箱做成链上可批量索引的永久名单。索引器凭 cardURI 取卡得到
///    agent_id 明文,回算 keccak 核对即可重建目录。
///    (边界:anchor 的 calldata 仍含明文 agentId —— 签名消息规范不变的代价;
///    事件哈希化挡住的是"扫日志批量收邮箱",不是逐笔翻 tx 的定向查看。)
/// 2. cardURI 取件指针:登记时附带"卡在哪取"(https URL / ipfs:// CID)。
///    指针进入签名消息,relayer 不能在验签通过后调换 URI;取到卡后仍须
///    回链核对 cardHash,假指针自然验不过。URI 不是内容信任根。
/// 3. rotateKey 换钥:旧钥签名授权把身份交给新钥,身份(agentId)不变。
///    换设备/钥匙轮换用;钥匙丢失(无法签名)仍只能 revoke 后重新注册。
///
/// meta-tx 设计与 V1 一致:所有写操作验的是【消息里的设备签名】(ecrecover),
/// msg.sender 无关紧要 —— 任何人都能代交、代付 gas,设备永不持币;
/// 签名规范与链下 registry(keysig.py)逐字节一致,插件端零迁移:
///   登记 message = "achat-yp-register|{agentId}|{cardHashHex}|{cardURI}|{ts}"
///   换钥 message = "achat-rotate|{agentId}|{newKeyLowerHex}|{ts}"
///   吊销 message = "achat-revoke|{agentId}|{ts}"
/// (均为 EIP-191 personal_sign)
contract AgentRegistryV2 {
    struct Agent {
        address key;        // 身份钥匙(首次登记即绑定,谁签谁拥有)
        bytes32 cardHash;   // 当前卡的 sha256(链下卡回链核对防篡改)
        uint64 updatedAt;   // 最近一次写操作的签名时间戳(单调递增,防重放)
        uint8 status;       // 1=active, 2=revoked(终态)
        string cardURI;     // 取件指针(进入签名;仍不是内容信任根)
    }

    // keccak(agentId) → Agent
    mapping(bytes32 => Agent) public agents;

    event Registered(bytes32 indexed agentIdHash, address indexed key,
                     bytes32 cardHash, string cardURI, uint64 ts);
    event Updated(bytes32 indexed agentIdHash, address indexed key,
                  bytes32 cardHash, string cardURI, uint64 ts);
    event KeyRotated(bytes32 indexed agentIdHash, address indexed oldKey,
                     address indexed newKey, uint64 ts);
    event Revoked(bytes32 indexed agentIdHash, address indexed key, uint64 ts);

    // ---------------------------------------------------------------
    // 写:登记/更新卡锚(签名 = 设备发卡时的同一个 EIP-191 签名)

    /// @param agentId     如 "pan@achat.email"
    /// @param cardHashHex 卡规范化 JSON 的 sha256,64 位小写 hex(与签名消息里一致)
    /// @param ts          签名时间戳(unix 秒;必须大于上次,防重放)
    /// @param sig         设备的 65 字节 EIP-191 签名
    /// @param cardURI     取件指针(可为空;进入签名,索引器取件后仍须回链核对)
    function anchor(string calldata agentId, string calldata cardHashHex,
                    uint64 ts, bytes calldata sig, string calldata cardURI) external {
        require(bytes(cardHashHex).length == 64, "bad hash len");
        address signer = _recover(
            string.concat("achat-yp-register|", agentId, "|", cardHashHex, "|",
                          cardURI, "|", _u64str(ts)),
            sig);
        bytes32 id = keccak256(bytes(agentId));
        Agent storage a = agents[id];
        require(a.status != 2, "revoked");
        require(ts > a.updatedAt, "stale ts");            // 旧签名不可重放
        bytes32 h = _hexToBytes32(cardHashHex);
        if (a.key == address(0)) {
            // 首次登记 = 绑定:谁签谁拥有(与链下 TOFU 语义一致)
            agents[id] = Agent(signer, h, ts, 1, cardURI);
            emit Registered(id, signer, h, cardURI, ts);
        } else {
            require(signer == a.key, "not owner key");    // 只有钥匙持有者能改
            a.cardHash = h;
            a.updatedAt = ts;
            a.cardURI = cardURI;
            emit Updated(id, signer, h, cardURI, ts);
        }
    }

    /// 换钥:旧钥签名授权,身份不变、钥匙轮换(换设备/定期轮换)。
    /// message = "achat-rotate|{agentId}|{newKeyLowerHex}|{ts}",newKey 为
    /// "0x"+40 位小写 hex(与链下 str(address).lower() 一致)。
    function rotateKey(string calldata agentId, address newKey,
                       uint64 ts, bytes calldata sig) external {
        require(newKey != address(0), "zero key");
        address signer = _recover(
            string.concat("achat-rotate|", agentId, "|", _addrLowerHex(newKey), "|",
                          _u64str(ts)),
            sig);
        bytes32 id = keccak256(bytes(agentId));
        Agent storage a = agents[id];
        require(a.key != address(0), "unknown agent");
        require(a.status == 1, "not active");
        require(signer == a.key, "not owner key");
        require(ts > a.updatedAt, "stale ts");
        address old = a.key;
        a.key = newKey;
        a.updatedAt = ts;
        emit KeyRotated(id, old, newKey, ts);
    }

    /// 吊销(钥匙泄露/设备丢失,终态)。message = "achat-revoke|{agentId}|{ts}"
    function revoke(string calldata agentId, uint64 ts, bytes calldata sig) external {
        address signer = _recover(
            string.concat("achat-revoke|", agentId, "|", _u64str(ts)), sig);
        bytes32 id = keccak256(bytes(agentId));
        Agent storage a = agents[id];
        require(a.key != address(0), "unknown agent");
        require(signer == a.key, "not owner key");
        require(ts > a.updatedAt, "stale ts");
        a.status = 2;
        a.updatedAt = ts;
        emit Revoked(id, signer, ts);
    }

    // ---------------------------------------------------------------
    // 读:验真入口(链下发现层拿到卡后回链核对)

    function verify(string calldata agentId, string calldata cardHashHex)
        external view returns (bool ok, address key, uint8 status)
    {
        Agent storage a = agents[keccak256(bytes(agentId))];
        return (a.status == 1 && a.cardHash == _hexToBytes32(cardHashHex),
                a.key, a.status);
    }

    function get(string calldata agentId)
        external view
        returns (address key, bytes32 cardHash, uint64 updatedAt, uint8 status,
                 string memory cardURI)
    {
        Agent storage a = agents[keccak256(bytes(agentId))];
        return (a.key, a.cardHash, a.updatedAt, a.status, a.cardURI);
    }

    /// 索引器用:按 agentIdHash 直查(事件里只有哈希,取卡验完 keccak 后也可反查)
    function getByHash(bytes32 agentIdHash)
        external view
        returns (address key, bytes32 cardHash, uint64 updatedAt, uint8 status,
                 string memory cardURI)
    {
        Agent storage a = agents[agentIdHash];
        return (a.key, a.cardHash, a.updatedAt, a.status, a.cardURI);
    }

    /// 调试/对齐用:链上按同一规范算出的 EIP-191 消息哈希(与链下 encode_defunct 对齐)
    function messageHash(string calldata agentId, string calldata cardHashHex,
                         uint64 ts, string calldata cardURI)
        external pure returns (bytes32)
    {
        return _ethHash(
            string.concat("achat-yp-register|", agentId, "|", cardHashHex, "|",
                          cardURI, "|", _u64str(ts)));
    }

    // ---------------------------------------------------------------
    // 内部:EIP-191 personal_sign 恢复

    function _recover(string memory message, bytes calldata sig) internal pure returns (address) {
        require(sig.length == 65, "bad sig len");
        bytes32 r; bytes32 s; uint8 v;
        assembly {
            r := calldataload(sig.offset)
            s := calldataload(add(sig.offset, 32))
            v := byte(0, calldataload(add(sig.offset, 64)))
        }
        if (v < 27) v += 27;
        require(v == 27 || v == 28, "bad v");
        address signer = ecrecover(_ethHash(message), v, r, s);
        require(signer != address(0), "bad sig");
        return signer;
    }

    function _ethHash(string memory message) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(
            "\x19Ethereum Signed Message:\n", _u64str(uint64(bytes(message).length)), message));
    }

    function _u64str(uint64 x) internal pure returns (string memory) {
        if (x == 0) return "0";
        uint64 t = x; uint256 len;
        while (t != 0) { len++; t /= 10; }
        bytes memory b = new bytes(len);
        while (x != 0) { len--; b[len] = bytes1(uint8(48 + x % 10)); x /= 10; }
        return string(b);
    }

    /// address → "0x"+40 位小写 hex(rotate 消息里 newKey 的文本形式)
    function _addrLowerHex(address a) internal pure returns (string memory) {
        bytes16 digits = "0123456789abcdef";
        bytes memory buf = new bytes(42);
        buf[0] = "0"; buf[1] = "x";
        uint160 v = uint160(a);
        for (uint256 i = 41; i > 1; i--) {
            buf[i] = digits[v & 0xf];
            v >>= 4;
        }
        return string(buf);
    }

    function _hexToBytes32(string calldata hexStr) internal pure returns (bytes32 out) {
        bytes memory b = bytes(hexStr);
        require(b.length == 64, "bad hex len");
        uint256 acc;
        for (uint256 i = 0; i < 64; i++) {
            uint8 c = uint8(b[i]);
            uint8 d;
            if (c >= 48 && c <= 57) d = c - 48;          // 0-9
            else if (c >= 97 && c <= 102) d = c - 87;    // a-f
            else if (c >= 65 && c <= 70) d = c - 55;     // A-F
            else revert("bad hex char");
            acc = (acc << 4) | d;
        }
        out = bytes32(acc);
    }
}
